const d = $input.first().json;
let arr = [];
try { arr = (typeof d.ingredients === 'string') ? JSON.parse(d.ingredients) : (d.ingredients || []); } catch (e) { arr = []; }
if (!Array.isArray(arr)) arr = [];
const names = arr.map(x => (x && typeof x === 'object') ? String(x.item || '') : String(x || '')).map(s => s.trim()).filter(Boolean);
return [{ json: { bot_id: d.bot_id, user_id: d.user_id, names } }];

const names = $('Разобрать').first().json.names || [];
const row = $input.first().json || {};
function pj(v){ if (typeof v === 'string'){ try { return JSON.parse(v); } catch(e){ return []; } } return v || []; }
let allergens = pj(row.allergens) || [];
let groups = pj(row.groups) || [];
let foods = pj(row.foods) || [];
if (!allergens.length) return [{ json: { response: 'У клиента в карте нет аллергий/непереносимостей — по этому критерию ограничений нет. Всё равно опирайся на состав продукта и здравый смысл.' } }];
const norm = s => String(s||'').toLowerCase().trim();
const sevRank = { allergy: 2, intolerance: 1 };
// синонимы и названия групп
const groupSyn = {}; const groupTitle = {};
for (const g of groups) { groupSyn[g.group_key] = (g.synonyms||[]).map(norm); groupTitle[g.group_key] = g.title_ru || g.group_key; }
// свести аллергены клиента к категориям (+ сохранить сырьё для прямого матча)
const clientGroups = {}; const clientRaw = [];
for (const a of allergens) {
  const sub = norm(a.substance); if (!sub) continue;
  clientRaw.push({ substance: sub, severity: a.severity });
  for (const gk in groupSyn) {
    let hit = false;
    for (const sy of groupSyn[gk]) { if (!sy) continue; if (sub === sy || sub.indexOf(sy) !== -1 || sy.indexOf(sub) !== -1) { hit = true; break; } }
    if (hit && (!clientGroups[gk] || sevRank[a.severity] > sevRank[clientGroups[gk]])) clientGroups[gk] = a.severity;
  }
}
// матч ингредиентов
const hits = [];
for (const nmRaw of names) {
  const nm = norm(nmRaw); if (!nm) continue;
  // 1. прямое вхождение сырья аллергена
  for (const c of clientRaw) { if (c.substance && nm.indexOf(c.substance) !== -1) hits.push({ ing: nmRaw, label: c.substance, severity: c.severity }); }
  // 2. категория по синониму группы в названии (напр. 'миндаль')
  for (const gk in clientGroups) { for (const sy of (groupSyn[gk]||[])) { if (sy && nm.indexOf(sy) !== -1) { hits.push({ ing: nmRaw, label: groupTitle[gk], severity: clientGroups[gk] }); break; } } }
  // 3. составной продукт по карте food_allergen
  for (const f of foods) { const ft = norm(f.food_term); if (!ft) continue; if ((nm.indexOf(ft) !== -1 || ft.indexOf(nm) !== -1) && clientGroups[f.group_key]) hits.push({ ing: nmRaw, label: groupTitle[f.group_key], severity: clientGroups[f.group_key] }); }
}
// дедуп по ing+label
const seen = new Set(); const uniq = [];
for (const h of hits) { const k = norm(h.ing)+'|'+norm(h.label); if (!seen.has(k)) { seen.add(k); uniq.push(h); } }
const block = uniq.filter(h => h.severity === 'allergy');
const warn = uniq.filter(h => h.severity === 'intolerance');
const parts = [];
if (block.length) parts.push('БЛОКИРОВКА (аллергия!): ' + block.map(h => h.ing + ' → ' + h.label).join('; ') + '. НЕ предлагай это клиенту, замени на безопасное.');
if (warn.length) parts.push('Предупреждение (непереносимость): ' + warn.map(h => h.ing + ' → ' + h.label).join('; ') + '. Предупреди клиента явно или замени.');
if (!parts.length) parts.push('Совпадений с аллергенами клиента не найдено (проверены прямые вхождения, категории — орехи, молоко, рыба и т.п. — и составные продукты по справочнику). ВАЖНО: справочник не полон. Если состав неизвестен или продукт может скрыто содержать аллерген клиента — не утверждай «можно», предупреди и предложи уточнить состав.');
return [{ json: { response: parts.join(' ') } }];
